B.aXL=new A.cW("luna_velada",B.eq,"Luna velada","Detr\xe1s de las nubes. Est\xe1, aunque no se vea entera.",B.dQ)
B.aXj=new A.cW("luna_gemela",B.eq,"Lunas gemelas","Dos lunas. Nadie ha explicado nunca de d\xf3nde sali\xf3 la segunda.",B.f3)
