B.aXd=new A.cW("est_linterna",B.dZ,"Linterna de piedra","T\u014dr\u014d. Encendida desde hace m\xe1s a\xf1os de los que nadie cuenta.",B.dQ)
B.aXT=new A.cW("est_campana",B.dZ,"La gran campana","Bonsh\u014d. Se golpea 108 veces al terminar el a\xf1o.",B.du)
B.aXP=new A.cW("est_castillo",B.dZ,"Castillo","Tejados escalonados sobre un muro que nadie tom\xf3.",B.f3)
B.aXn=new A.cW("est_torii_doble",B.dZ,"Sendero de torii","Puerta tras puerta, hasta que se pierde la cuenta.",B.fz)
B.aXD=new A.cW("veg_arce",B.er,"Arce rojo","Momiji en oto\xf1o. Dura tres semanas al a\xf1o.",B.dQ)
B.aXJ=new A.cW("veg_glicina",B.er,"Glicinas","Racimos violeta colgando sobre el agua.",B.du)
B.aXW=new A.cW("veg_loto",B.er,"Lotos","Nacen del barro y salen limpios. Por eso est\xe1n aqu\xed.",B.du)
B.aXv=new A.cW("veg_sakura_nocturno",B.er,"Cerezo nocturno","Yozakura: el cerezo iluminado por dentro.",B.f3)
B.aXV=new A.cW("cri_luciernagas",B.d7,"Luci\xe9rnagas","Hotaru. Aparecen una semana al a\xf1o y desaparecen.",B.dQ)
B.aXQ=new A.cW("cri_cuervos",B.d7,"Cuervos","Tres. Siempre tres, y siempre mirando al mismo sitio.",B.dQ)
