B.bqj=new A.uC("El Clan","\u65cf","Aqu\xed solo se habla de progreso.",B.aF0)
B.boF=new A.fK(B.i1,"La silueta","Cada m\xfasculo brilla con el color de su rango. Toca los que quieras entrenar y pulsa \xabForjar sesi\xf3n\xbb.")
B.boW=new A.fK(B.kL,"Honor","Cada serie dura suma honor a los m\xfasculos que trabaja. La bendici\xf3n del d\xeda da +25 % a tu m\xfasculo m\xe1s olvidado.")
B.boE=new A.fK(B.kH,"Rangos y premios","De Ashigaru a Kami: 22 rangos por m\xfasculo. Cada ascenso da mon, y los tiers altos regalan piezas del Taller.")
B.boJ=new A.fK(B.wT,"Tabla del clan","Compite con las personas que sigues, en total o m\xfasculo por m\xfasculo.")
